WITH s AS (
  SELECT app_id, channel, new_user, recharge_amount FROM ads.ads_channel_summary_d_paimon_shadow WHERE date_key='2026-11-12'
), f AS (
  SELECT app_id, channel, new_user, recharge_amount FROM ads.ads_channel_summary_d WHERE date_key='2026-11-12'
), of AS (
  SELECT f.* FROM f LEFT JOIN s ON f.app_id=s.app_id AND f.channel=s.channel WHERE s.app_id IS NULL
), os AS (
  SELECT s.* FROM s LEFT JOIN f ON s.app_id=f.app_id AND s.channel=f.channel WHERE f.app_id IS NULL
)
SELECT 'only_formal' AS cls, COUNT(*) AS keys, SUM(new_user) AS new_sum, SUM(recharge_amount) AS recharge_sum FROM of
UNION ALL
SELECT 'only_shadow', COUNT(*), SUM(new_user), SUM(recharge_amount) FROM os

